//! Parity of the native utilities of phase 11a with BoTorch, from the
//! fixtures in `tests/fixtures/11a-utils/*.json` (generated by
//! `scripts/generate_fixtures.py --phase 11a-utils`):
//!
//! * `elementwise.json`, `reductions.json`: the element-wise and reduction
//!   kernels of `safe_math` and `utils.probability` (values 1e-9, gradients
//!   1e-8 relative; BoTorch's non-finite gradients are skipped);
//! * `probability.json`: `compute_log_prob_feas_from_bounds` (with
//!   gradients) and `percentile_of_score`;
//! * `mvnxpb.json`: `MVNXPB` log probabilities and gradients,
//!   `augment_cholesky`;
//! * `lin_ess.json`: linear elliptical slice sampling chains with BoTorch's
//!   random numbers (BoTorch's 2 pi wrapping constant in float64);
//! * `rng_qmc.json`: torch's CPU generator (bitwise) and the normal QMC
//!   transforms;
//! * `test_functions.json`: the single-objective test problems.
//!
//! Run with `--nocapture` to print the error tables.

mod common;

use botorch_core::test_functions::single_objective::TrajectoryConfig;
use botorch_core::test_functions::{SingleObjectiveKind, SingleObjectiveProblem};
use botorch_core::utils::elementwise::{
    elementwise, log_prob_feas_from_bounds, percentile_of_score, reduce, OutcomeBounds,
};
use botorch_core::utils::lin_ess::{CovarianceRoot, LinearEllipticalSliceSampler};
use botorch_core::utils::mvnxpb::mvnxpb_log_prob_with_grad;
use botorch_core::utils::mvnxpb_state::augment_cholesky;
use botorch_core::utils::qmc::normal_qmc_transform;
use botorch_core::utils::torch_rng::TorchGenerator;
use botorch_core::{Matrix, Vector};
use common::{fixture_dir, flatten, matrix, matrix_rows, rel_err, Report};
use serde::de::DeserializeOwned;
use serde::Deserialize;

const TOL: f64 = 1e-9;
const GTOL: f64 = 1e-8;

fn load<T: DeserializeOwned>(name: &str) -> T {
    let path = fixture_dir().join("11a-utils").join(name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap()
}

/// The relative error over the entries where BoTorch's value is finite
/// (`None` in the fixture).
fn rel_err_finite(actual: &[f64], expected: &[Option<f64>]) -> f64 {
    let (a, e): (Vec<f64>, Vec<f64>) = actual
        .iter()
        .zip(expected)
        .filter_map(|(a, e)| e.map(|e| (*a, e)))
        .unzip();
    if e.is_empty() {
        0.0
    } else {
        rel_err(&a, &e)
    }
}

// ---------------------------------------------------------------------------
// Element-wise kernels and reductions
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct ElementwiseCase {
    name: String,
    inputs: Vec<Vec<f64>>,
    params: Vec<f64>,
    values: Vec<Vec<f64>>,
    grads: Vec<Vec<Vec<Option<f64>>>>,
}

#[test]
fn elementwise_kernels_match_botorch() {
    let cases: Vec<ElementwiseCase> = load("elementwise.json");
    let mut report = Report::default();
    for c in &cases {
        let inputs: Vec<&[f64]> = c.inputs.iter().map(Vec::as_slice).collect();
        let out = elementwise(&c.name, &inputs, &c.params, false, true).unwrap();
        for (o, expected) in c.values.iter().enumerate() {
            report.check_slices(&c.name, "values", &out.values[o], expected, TOL);
        }
        let grads = out.grads.unwrap();
        for (o, per_input) in c.grads.iter().enumerate() {
            for (k, expected) in per_input.iter().enumerate() {
                report.check(
                    &c.name,
                    "gradients",
                    rel_err_finite(&grads[o][k], expected),
                    GTOL,
                );
            }
        }
    }
    report.finish("11a element-wise kernels vs BoTorch");
}

#[derive(Deserialize)]
struct ReductionCase {
    name: String,
    x: Vec<Vec<f64>>,
    params: Vec<f64>,
    values: Vec<f64>,
    grads: Vec<Vec<Option<f64>>>,
}

#[test]
fn reductions_match_botorch() {
    let cases: Vec<ReductionCase> = load("reductions.json");
    let mut report = Report::default();
    for c in &cases {
        let n = c.x[0].len();
        let (values, grads) = reduce(&c.name, &flatten(&c.x), n, &c.params, true).unwrap();
        report.check_slices(&c.name, "values", &values, &c.values, TOL);
        let expected: Vec<Option<f64>> = c.grads.iter().flatten().copied().collect();
        report.check(
            &c.name,
            "gradients",
            rel_err_finite(&grads.unwrap(), &expected),
            GTOL,
        );
    }
    report.finish("11a reductions vs BoTorch");
}

#[derive(Deserialize)]
struct Feasibility {
    lower: Vec<(usize, f64)>,
    upper: Vec<(usize, f64)>,
    both: Vec<(usize, f64, f64)>,
    means: Vec<Vec<f64>>,
    sigmas: Vec<Vec<f64>>,
    values: Vec<f64>,
    grad_means: Vec<Vec<Option<f64>>>,
    grad_sigmas: Vec<Vec<Option<f64>>>,
}

#[derive(Deserialize)]
struct Percentile {
    data: Vec<Vec<f64>>,
    scores: Vec<f64>,
    values: Vec<f64>,
}

#[derive(Deserialize)]
struct ProbabilityFixture {
    feasibility: Feasibility,
    percentile: Percentile,
}

#[test]
fn probability_utilities_match_botorch() {
    let f: ProbabilityFixture = load("probability.json");
    let mut report = Report::default();
    let p = &f.feasibility;
    let bounds = OutcomeBounds {
        lower: p.lower.clone(),
        upper: p.upper.clone(),
        both: p.both.clone(),
    };
    let m = p.means[0].len();
    let (values, grads) =
        log_prob_feas_from_bounds(&bounds, &flatten(&p.means), &flatten(&p.sigmas), m, true)
            .unwrap();
    report.check_slices("feasibility", "values", &values, &p.values, TOL);
    let (gm, gs) = grads.unwrap();
    let em: Vec<Option<f64>> = p.grad_means.iter().flatten().copied().collect();
    let es: Vec<Option<f64>> = p.grad_sigmas.iter().flatten().copied().collect();
    report.check("feasibility", "grad means", rel_err_finite(&gm, &em), GTOL);
    report.check("feasibility", "grad sigmas", rel_err_finite(&gs, &es), GTOL);
    let q = &f.percentile;
    let n = q.data[0].len();
    // BoTorch computes in torch's default dtype (float32).
    let values = percentile_of_score(&flatten(&q.data), &q.scores, n, true);
    report.check_slices("percentile_of_score", "values", &values, &q.values, 0.0);
    report.finish("11a probability utilities vs BoTorch");
}

// ---------------------------------------------------------------------------
// MVNXPB and augment_cholesky
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct MvnxpbCase {
    cov: Vec<Vec<f64>>,
    bounds: Vec<Vec<Option<f64>>>,
    log_prob: f64,
    grad_cov: Vec<Vec<f64>>,
    grad_bounds: Vec<Vec<Option<f64>>>,
}

#[derive(Deserialize)]
struct Augment {
    #[serde(rename = "K")]
    k: Vec<Vec<f64>>,
    na: usize,
    #[serde(rename = "L")]
    l: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct MvnxpbFixture {
    cases: Vec<MvnxpbCase>,
    augment: Augment,
}

#[test]
fn mvnxpb_matches_botorch() {
    let f: MvnxpbFixture = load("mvnxpb.json");
    let mut report = Report::default();
    for (i, c) in f.cases.iter().enumerate() {
        let label = format!("MVNXPB case {i} (d = {})", c.cov.len());
        let bounds: Vec<Vec<f64>> = c
            .bounds
            .iter()
            .map(|row| {
                vec![
                    row[0].unwrap_or(f64::NEG_INFINITY),
                    row[1].unwrap_or(f64::INFINITY),
                ]
            })
            .collect();
        let (lp, gc, gb) = mvnxpb_log_prob_with_grad(&matrix(&c.cov), &matrix(&bounds)).unwrap();
        report.check_slices(&label, "log_prob", &[lp], &[c.log_prob], TOL);
        report.check_slices(
            &label,
            "grad cov",
            &matrix_rows(&gc),
            &flatten(&c.grad_cov),
            GTOL,
        );
        let eb: Vec<Option<f64>> = c.grad_bounds.iter().flatten().copied().collect();
        report.check(
            &label,
            "grad bounds",
            rel_err_finite(&matrix_rows(&gb), &eb),
            GTOL,
        );
    }
    let a = &f.augment;
    let k = matrix(&a.k);
    let n = k.nrows();
    let na = a.na;
    let laa = k
        .view((0, 0), (na, na))
        .into_owned()
        .cholesky()
        .unwrap()
        .l();
    let kbb = k.view((na, na), (n - na, n - na)).into_owned();
    let kba = k.view((na, 0), (n - na, na)).into_owned();
    let l = augment_cholesky(&laa, &kbb, Some(&kba), None, None).unwrap();
    report.check_slices(
        "augment_cholesky",
        "factor",
        &matrix_rows(&l),
        &flatten(&a.l),
        TOL,
    );
    report.finish("11a MVNXPB vs BoTorch");
}

// ---------------------------------------------------------------------------
// Linear elliptical slice sampling
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct LinEssCase {
    label: String,
    #[serde(rename = "A")]
    a: Vec<Vec<f64>>,
    b: Vec<f64>,
    x0: Vec<f64>,
    num_chains: usize,
    nu: Vec<Vec<f64>>,
    u: Vec<Vec<f64>>,
    samples: Vec<Vec<f64>>,
    covariance_matrix: Option<Vec<Vec<f64>>>,
    mean: Option<Vec<f64>>,
    fixed_indices: Option<Vec<usize>>,
    root_diag: Option<Vec<f64>>,
}

#[test]
fn lin_ess_chains_match_botorch() {
    let cases: Vec<LinEssCase> = load("lin_ess.json");
    let mut report = Report::default();
    for c in &cases {
        let mut s = LinearEllipticalSliceSampler::new(
            matrix(&c.a),
            Vector::from_vec(c.b.clone()),
            Vector::from_vec(c.x0.clone()),
            c.fixed_indices.clone(),
            c.mean.as_ref().map(|m| Vector::from_vec(m.clone())),
            c.covariance_matrix.as_ref().map(|m| matrix(m)),
            c.root_diag
                .as_ref()
                .map(|d| CovarianceRoot::Diagonal(Vector::from_vec(d.clone()))),
            c.num_chains,
            false,
        )
        .unwrap();
        let k = s.free_dim();
        let mut worst = 0.0f64;
        for (step, (nu, u)) in c.nu.iter().zip(&c.u).enumerate() {
            let dir = Matrix::from_row_slice(k, c.num_chains, nu);
            let x = s.step(&dir, u, true).unwrap();
            // BoTorch's samples are chain-major (`x.T`).
            let actual: Vec<f64> = (0..x.ncols())
                .flat_map(|j| (0..x.nrows()).map(move |i| (i, j)))
                .map(|(i, j)| x[(i, j)])
                .collect();
            worst = worst.max(rel_err(&actual, &c.samples[step]));
        }
        report.check(&c.label, "chain", worst, TOL);
        assert_eq!(s.lifetime_samples(), c.nu.len());
    }
    report.finish("11a LinESS vs BoTorch");
}

// ---------------------------------------------------------------------------
// torch's generator and the normal QMC transforms
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct RngCase {
    seed: u64,
    n: usize,
    randn: Vec<f64>,
    rand: Vec<f64>,
    rand32: Vec<f64>,
}

#[derive(Deserialize)]
struct QmcCase {
    d: usize,
    inv_transform: bool,
    sobol_dim: usize,
    uniform: Vec<Vec<f64>>,
    samples: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct RngQmcFixture {
    rng: Vec<RngCase>,
    qmc: Vec<QmcCase>,
}

#[test]
fn torch_generator_and_qmc_match_torch() {
    let f: RngQmcFixture = load("rng_qmc.json");
    for c in &f.rng {
        assert_eq!(
            TorchGenerator::new(c.seed).randn(c.n),
            c.randn,
            "randn {}",
            c.seed
        );
        assert_eq!(
            TorchGenerator::new(c.seed).rand(c.n),
            c.rand,
            "rand {}",
            c.seed
        );
        let r32: Vec<f64> = TorchGenerator::new(c.seed)
            .rand_f32(c.n)
            .into_iter()
            .map(f64::from)
            .collect();
        assert_eq!(r32, c.rand32, "rand float32 {}", c.seed);
    }
    let mut report = Report::default();
    for c in &f.qmc {
        let n = c.uniform.len();
        let out = normal_qmc_transform(
            &flatten(&c.uniform),
            n,
            c.sobol_dim,
            c.d,
            c.inv_transform,
            false,
        )
        .unwrap();
        let label = format!("NormalQMCEngine d={} inv={}", c.d, c.inv_transform);
        report.check_slices(&label, "samples", &out, &flatten(&c.samples), TOL);
    }
    report.finish("11a QMC transforms vs BoTorch");
}

// ---------------------------------------------------------------------------
// Test functions
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct ProblemCase {
    name: String,
    dim: usize,
    bounds: Vec<Vec<f64>>,
    discrete: Vec<usize>,
    params: Vec<f64>,
    #[serde(rename = "X")]
    x: Vec<Vec<f64>>,
    values: Vec<f64>,
    slack: Option<Vec<Vec<f64>>>,
    cost: Option<Vec<f64>>,
    use_smooth_interp: Option<bool>,
    max_step_size: Option<f64>,
}

#[test]
fn test_functions_match_botorch() {
    let cases: Vec<ProblemCase> = load("test_functions.json");
    let mut report = Report::default();
    for c in &cases {
        let kind = SingleObjectiveKind::from_name(&c.name).unwrap();
        let trajectory = c.use_smooth_interp.map(|smooth| TrajectoryConfig {
            use_smooth_interp: smooth,
            max_step_size: c.max_step_size.unwrap(),
        });
        let p = SingleObjectiveProblem::new(
            kind,
            c.dim,
            matrix(&c.bounds),
            c.discrete.clone(),
            c.params.clone(),
            trajectory,
        )
        .unwrap();
        let x = matrix(&c.x);
        report.check_slices(
            &c.name,
            "values",
            &p.evaluate_true(&x).unwrap(),
            &c.values,
            TOL,
        );
        if let Some(slack) = &c.slack {
            let s = p.evaluate_slack_true(&x).unwrap();
            report.check_slices(&c.name, "slack", &matrix_rows(&s), &flatten(slack), TOL);
        }
        if let Some(cost) = &c.cost {
            report.check_slices(&c.name, "cost", &p.cost(&x).unwrap(), cost, TOL);
        }
    }
    report.finish("11a test functions vs BoTorch");
}
